blocks.mapping:
data && { 
    parties: data[0][].{ type: `party`, id: uuid(), name: @ }, 
    licenses: data[1][].{ type: `license`, id: uuid(), name: @ }, 
    vendors: data[2][].{ type: `platform`, id: uuid(), name: @ }, 
    works: data[3][].merge(@, { id: uuid(), type: `work` }) 
}

data && merge(data,
    { works: data.works[].merge(@, { 
        assetManager: find($.data.parties, 'name', assetManager).id, 
        owner: owner[].find($.data.parties, 'name', name).{ partyId: id, split: `0` }, 
        vendors: vendors[].find($.data.vendors, 'name', @).{ marketId: id },
        beneficiaries: beneficiaries[].find($.data.parties, 'name', name).{ partyId: id, split: `0` }, 
        licenseDetails: find($.data.licenses, 'name', licenseDetails).id 
    }) 
})

data.parties && data.[parties, licenses, vendors, works][]
    .merge(@, 
        { 
            uuid: id, 
            schema: type 
        }
    )
